/**
 * AudioWorklet processor for voice-kit adapter-web.
 *
 * Pillar #1: Writes Int16 PCM into a SharedArrayBuffer ring buffer when SAB is
 * available (requires crossOriginIsolated). Falls back to MessagePort postMessage
 * with a transferred Int16Array otherwise.
 *
 * Responsibilities:
 *   - Float32 → Int16 conversion
 *   - Polyphase FIR resampling (48kHz → 16kHz, eliminates aliasing)
 *   - RMS / chunk-id stamping per frame
 *   - Underrun detection (>50ms between process() calls)
 */

// ============================================
// Auto-generated by scripts/generate-polyphase-coeffs.js
// DO NOT EDIT — regenerate with: node scripts/generate-polyphase-coeffs.js
// ============================================
// Filter: 64-tap Kaiser windowed sinc, beta=5.653, cutoff=0.15
// Downsampling: 3:1 (48kHz -> 16kHz)
// 旁瓣衰减: ~60dB, 过渡带: 7600Hz - 8400Hz (5%)

const FILTER_PHASE_0 = new Int16Array([
  -73, 209, -347, 435, -410, 201, 282, -1166,
  2738, -6032, 20535, 20535, -6032, 2738, -1166, 282,
  201, -410, 435, -347, 209, -73,
]);
const FILTER_PHASE_1 = new Int16Array([
  -53, 188, -408, 694, -1005, 1279, -1428, 1325,
  -712, -1376, 28390, 8775, -4870, 3302, -2245, 1432,
  -809, 363, -83, -51, 73, 0,
]);
const FILTER_PHASE_2 = new Int16Array([
  73, -51, -83, 363, -809, 1432, -2245, 3302,
  -4870, 8775, 28390, -1376, -712, 1325, -1428, 1279,
  -1005, 694, -408, 188, -53, 0,
]);

/**
 * Polyphase FIR 降采样: 48kHz -> 16kHz (3:1)
 * 用 3 个预计算的子滤波器轮流处理, 避免直接降采样导致的混叠失真
 *
 * @param {Float32Array} input - 48kHz 输入
 * @returns {Float32Array} - 16kHz 输出
 */
function resamplePolyphase(input) {
  const DOWNSAMPLE = 3;
  const outLen = Math.floor(input.length / DOWNSAMPLE);
  const out = new Float32Array(outLen);
  const phases = [FILTER_PHASE_0, FILTER_PHASE_1, FILTER_PHASE_2];

  // 正确的 Polyphase 降采样: 对每个输出 m, 计算 y[m*L] = Σ h[j] * input[m*L - j]
  // 把 h 按 j = Lk + p 分解到 L 个 polyphase 分支, 每个分支用 stride-L 的输入索引
  // 这样所有 64 个滤波器系数都对每个输出有贡献, 才是真正的低通 + 降采样
  for (let i = 0; i < outLen; i++) {
    let acc = 0;
    for (let p = 0; p < DOWNSAMPLE; p++) {
      const branch = phases[p];
      for (let k = 0; k < branch.length; k++) {
        const idx = i * DOWNSAMPLE - (DOWNSAMPLE * k + p);
        if (idx >= 0 && idx < input.length) {
          acc += branch[k] * input[idx];
        }
      }
    }
    // 除以 DOWNSAMPLE 归一化 DC 增益 (因为所有分支之和 = L)
    out[i] = acc / (32768 * DOWNSAMPLE);
  }
  return out;
}

class CaptureProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const opts = options.processorOptions || {};
    this.targetRate = opts.targetRate || 16000;
    this.capacity = opts.capacity || 16000 * 4; // 4 seconds at 16k
    this.useSAB = !!opts.dataSAB && !!opts.indexSAB;

    if (this.useSAB) {
      this.data = new Int16Array(opts.dataSAB);
      this.idx = new Int32Array(opts.indexSAB); // [writePos, readPos, chunkId, overflowCount]
      this.writePos = 0;
    } else {
      this.frameBuffer = [];
    }
    this.chunkId = 0;
    this.lastTickTime = currentTime;
    this.overflowEmittedAt = 0;

    // Polyphase 滤波器状态: 跨帧输入历史 (FILTER_LEN - 1 个样本)
    this.filterHistory = new Float32Array(FILTER_PHASE_0.length * 3 - 1);
    this.historyLen = 0;

    this.port.onmessage = (e) => {
      if (e.data?.type === 'configure') {
        this.targetRate = e.data.targetRate ?? this.targetRate;
      }
    };
  }

  process(inputs) {
    const input = inputs[0]?.[0];
    if (!input || input.length === 0) return true;

    // Underrun detection: if >50ms passed since last tick, audio graph was starved
    const dt = currentTime - this.lastTickTime;
    if (dt > 0.05 && this.overflowEmittedAt + 1 < currentTime) {
      try {
        this.port.postMessage({ type: 'underrun', dt });
        this.overflowEmittedAt = currentTime;
      } catch {
        /* port closed */
      }
    }
    this.lastTickTime = currentTime;

    // Polyphase FIR 重采样 (48kHz -> 16kHz)
    // 如果不是 3:1 降采样, 退回到简单重采样
    let resampled;
    if (sampleRate === 48000 && this.targetRate === 16000) {
      // 拼接历史 + 当前输入
      const combined = new Float32Array(this.historyLen + input.length);
      combined.set(this.filterHistory.subarray(0, this.historyLen), 0);
      combined.set(input, this.historyLen);
      resampled = resamplePolyphase(combined);

      // 保存尾部作为下一帧的历史
      const newHistoryLen = Math.min(this.filterHistory.length, combined.length);
      this.filterHistory.set(combined.subarray(combined.length - newHistoryLen));
      this.historyLen = newHistoryLen;
    } else {
      // 非标准降采样比: 简单最近邻 (作为 fallback)
      const ratio = sampleRate / this.targetRate;
      const outLen = Math.max(1, Math.floor(input.length / ratio));
      resampled = new Float32Array(outLen);
      for (let i = 0; i < outLen; i++) {
        const srcIdx = Math.min(input.length - 1, Math.floor(i * ratio));
        resampled[i] = input[srcIdx];
      }
    }

    // Float32 → Int16
    const outLen = resampled.length;
    const int16 = new Int16Array(outLen);
    for (let i = 0; i < outLen; i++) {
      const s = Math.max(-1, Math.min(1, resampled[i]));
      int16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
    }

    this.chunkId++;

    if (this.useSAB) {
      // Write into the ring buffer (wrap around)
      for (let i = 0; i < int16.length; i++) {
        this.data[(this.writePos + i) % this.capacity] = int16[i];
      }
      this.writePos = (this.writePos + int16.length) % this.capacity;

      // Check overflow: read pointer far behind
      const readPos = Atomics.load(this.idx, 1);
      let lag = this.writePos - readPos;
      if (lag < 0) lag += this.capacity;
      if (lag > this.capacity * 0.9) {
        Atomics.add(this.idx, 3, 1);
      }

      // Publish writePos + chunkId and notify the consumer.
      // IMPORTANT: notify on slot 2 (chunkId) — the main-thread consumer's
      // Atomics.waitAsync is registered on slot 2. Notifying slot 0 here
      // would never wake the consumer (different slot index = different
      // wait queue in the Atomics semantics).
      Atomics.store(this.idx, 0, this.writePos);
      Atomics.store(this.idx, 2, this.chunkId);
      Atomics.notify(this.idx, 2, 1);
    } else {
      // Fallback: transfer a copy
      const copy = new Int16Array(outLen);
      copy.set(int16);
      const ts = performance.now ? performance.now() : Date.now();
      this.port.postMessage(
        {
          type: 'chunk',
          data: copy.buffer,
          chunkId: this.chunkId,
          captureTsMono: ts,
        },
        [copy.buffer]
      );
    }
    return true;
  }
}

registerProcessor('vk-capture-processor', CaptureProcessor);
